contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable {
        uint256 ownerBalBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 totalSupplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        require(amount <= ownerBalBefore);

        bool reverted;
        c.burn(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 ownerBalAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 totalSupplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;

        assert(reverted || (ownerBalAfter == ownerBalBefore - amount && totalSupplyAfter == totalSupplyBefore - amount));
    }

    receive() external payable {}
}

